def second_highest(scores):
    # Find the second highest distinct score
    if len(scores) < 2:
        return None
    highest = None
    second = None
    for s in scores:
        if highest is None or s > highest:
            second = highest
            highest = s
        elif s != highest:
            if second is None or s > second:
                second = s
    return second

print(second_highest([3, 1, 4, 1, 5]))

